import React, { useEffect, useState } from "react";
import axios from "axios";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [report, setReport] = useState(null);

  const token = localStorage.getItem("token"); // assuming token stored here
  const config = { headers: { Authorization: `Bearer ${token}` } };

  // Fetch voting state
  const fetchVotingState = async () => {
    try {
      const res = await axios.get("/api/admin/toggle-voting", config);
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error("Fetch voting state failed:", err);
    }
  };

  // Toggle voting
  const toggleVoting = async () => {
    try {
      const res = await axios.post("/api/admin/toggle-voting", {}, config);
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error("Toggle voting failed:", err);
    }
  };

  // Fetch pending users
  const fetchPendingUsers = async () => {
    try {
      const res = await axios.get("/api/admin/pending-users", config);
      setPendingUsers(res.data);
    } catch (err) {
      console.error("Fetch pending users failed:", err);
    }
  };

  // Approve user
  const approveUser = async (id) => {
    try {
      await axios.post(`/api/admin/approve-user/${id}`, {}, config);
      fetchPendingUsers();
    } catch (err) {
      console.error("Approve user failed:", err);
    }
  };

  // Reject user
  const rejectUser = async (id) => {
    try {
      await axios.post(`/api/admin/reject-user/${id}`, {}, config);
      fetchPendingUsers();
    } catch (err) {
      console.error("Reject user failed:", err);
    }
  };

  // Fetch candidates
  const fetchCandidates = async () => {
    try {
      const res = await axios.get("/api/admin/candidates", config);
      setCandidates(res.data);
    } catch (err) {
      console.error("Fetch candidates failed:", err);
    }
  };

  // Delete candidate
  const deleteCandidate = async (id) => {
    try {
      await axios.delete(`/api/admin/candidates/${id}`, config);
      fetchCandidates();
    } catch (err) {
      console.error("Delete candidate failed:", err);
    }
  };

  // Fetch logs
  const fetchLogs = async () => {
    try {
      const res = await axios.get("/api/admin/logs", config);
      setLogs(res.data);
    } catch (err) {
      console.error("Fetch logs failed:", err);
    }
  };

  // Generate report
  const generateReport = async () => {
    try {
      const res = await axios.post("/api/admin/generate-report", {}, config);
      setReport(res.data.hash);
    } catch (err) {
      console.error("Generate report failed:", err);
    }
  };

  useEffect(() => {
    fetchVotingState();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  return (
    <div className="admin-dashboard">
      <h1>Admin Dashboard</h1>

      <section>
        <h2>Voting Control</h2>
        <p>Voting is currently: {votingOpen ? "Open" : "Closed"}</p>
        <button onClick={toggleVoting}>
          {votingOpen ? "Close Voting" : "Open Voting"}
        </button>
      </section>

      <section>
        <h2>Pending Voter Registrations</h2>
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {pendingUsers.length === 0 ? (
              <tr>
                <td colSpan="3">No pending users</td>
              </tr>
            ) : (
              pendingUsers.map((user) => (
                <tr key={user.id}>
                  <td>{user.name}</td>
                  <td>{user.email}</td>
                  <td>
                    <button onClick={() => approveUser(user.id)}>Approve</button>
                    <button onClick={() => rejectUser(user.id)}>Reject</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </section>

      <section>
        <h2>Candidates</h2>
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Position</th>
              <th>Party</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {candidates.length === 0 ? (
              <tr>
                <td colSpan="4">No candidates</td>
              </tr>
            ) : (
              candidates.map((c) => (
                <tr key={c.id}>
                  <td>{c.name}</td>
                  <td>{c.position}</td>
                  <td>{c.party || "-"}</td>
                  <td>
                    <button onClick={() => deleteCandidate(c.id)}>Delete</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </section>

      <section>
        <h2>System Logs</h2>
        <ul>
          {logs.map((log) => (
            <li key={log.id}>
              [{new Date(log.createdAt).toLocaleString()}] {log.action}
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h2>Generate Report</h2>
        <button onClick={generateReport}>Generate Report</button>
        {report && <p>Report hash: {report}</p>}
      </section>
    </div>
  );
}
